// Extract request ID from topic
const parts = msg.topic.split('/');
const requestId = parts[parts.length - 1];

msg.rpcRequestId = requestId;
msg.rpcResponseTopic = 'v1/devices/me/rpc/response/' + requestId;

const rpc = msg.payload || {};
msg.rpcMethod = rpc.method;
msg.rpcParams = rpc.params || {};

// Only handle flow management methods
const validMethods = ['getFlows', 'setFlows', 'deleteFlows'];

if (!validMethods.includes(msg.rpcMethod)) {
    return null;
}

node.status({fill: 'blue', shape: 'dot', text: msg.rpcMethod});
return msg;

// Get flows from RPC params
const flows = msg.rpcParams.flows || msg.rpcParams;

if (!flows || !Array.isArray(flows)) {
    msg.payload = {
        success: false,
        error: 'Invalid flows data. Expected array.'
    };
    msg.statusCode = 400;
    return [null, msg];
}

msg.payload = flows;
msg.headers = {
    'Content-Type': 'application/json',
    'Node-RED-Deployment-Type': msg.rpcParams.deploymentType || 'full'
};

return [msg, null];

// Delete all flows by posting empty array
msg.payload = [];
msg.headers = {
    'Content-Type': 'application/json',
    'Node-RED-Deployment-Type': 'full'
};
return msg;

const method = msg.rpcMethod;
const statusCode = msg.statusCode || 200;

let response = {};

if (method === 'getFlows') {
    response = {
        success: true,
        flowCount: Array.isArray(msg.payload) ? msg.payload.length : 0,
        flows: msg.payload
    };
} else if (method === 'setFlows') {
    response = {
        success: statusCode === 200 || statusCode === 204,
        message: 'Flows deployed successfully'
    };
} else if (method === 'deleteFlows') {
    response = {
        success: statusCode === 200 || statusCode === 204,
        message: 'All flows deleted'
    };
}

if (statusCode >= 400) {
    response.success = false;
    response.error = msg.payload || 'Unknown error';
}

msg.payload = response;
msg.topic = msg.rpcResponseTopic;

node.status({
    fill: response.success ? 'green' : 'red',
    shape: 'dot',
    text: method + ': ' + (response.success ? 'OK' : 'FAIL')
});

return msg;
